public class Main{static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;}public static void main(String[]a){java.util.ArrayList<String> words=new java.util.ArrayList<>(100000); long r=12345; for(int i=0;i<100000;i++){r=xsNext(r); int len=3+(int)Long.remainderUnsigned(r,18); StringBuilder sb=new StringBuilder(); for(int j=0;j<len;j++){r=xsNext(r); sb.append((char)('a'+Long.remainderUnsigned(r,26)));} words.add(sb.toString());} long total=0; for(int p=0;p<4;p++) for(String w:words) total+=w.length()+w.charAt(0)+w.charAt(w.length()-1); System.out.println(words.size()); System.out.println(Long.toUnsignedString(total));}}